// Використання GeoJS для автоматичного визначення міста/країни
fetch('https://get.geojs.io/v1/ip/geo.json')
  .then(res => res.json())
  .then(data => {
    const country = data.country || "";
    const city = data.city || "";

    window._ax.Geo.getCoordinatesByCountryCity(country, city, function(coords) {
      const lat = coords.lat;
      const lon = coords.lon;

      const markersList = [
        { lat: lat - .011, lon: lon + .06 },
        { lat: lat - .02, lon: lon + .01 },
        { lat: lat + .01, lon: lon + .02 },
        { lat: lat + 0.0005, lon: lon - 0.005 },
        { lat: lat + .012, lon: lon - .035 },
        { lat: lat + .001, lon: lon - .045 },
        { lat: lat + .009, lon: lon - .07 },
        { lat: lat - .005, lon: lon + .02 },
        { lat: lat + .008, lon: lon + .055 },
        { lat: lat - .02, lon: lon + .03 },
        { lat: lat + .002, lon: lon + .05 },
        { lat: lat - .01, lon: lon - .07 }
      ];

      const mapInstance = new window._ax.Geo({
        coordinates: coords,
        markersList: markersList
      });

      const setMapView = (inst, lat, lon) => {
        inst.setView(lat, lon);
        const w = window.innerWidth;
        if (w > 1919) inst.setZoom(14);
        else if (w > 743) inst.setZoom(13);
        else inst.setZoom(12);
      };

      setMapView(mapInstance, lat, lon);

      window.addEventListener('resize', () => {
        setMapView(mapInstance, lat, lon);
      });
    });
  })
  .catch(err => console.error("GeoJS error:", err));
